<?php
declare(strict_types=1);
final class AdminReportModel
{
 public function dashboard(string $from,string $to,array $pagination=[]):array{$d=Database::connection();$range=['from'=>$from.' 00:00:00','to'=>$to.' 23:59:59'];$summary=['users'=>$this->count($d,'SELECT COUNT(*) FROM users WHERE created_at BETWEEN :from AND :to',$range),'projects'=>$this->count($d,'SELECT COUNT(*) FROM projects WHERE created_at BETWEEN :from AND :to',$range),'deliveries'=>$this->count($d,'SELECT COUNT(*) FROM project_deliveries WHERE submitted_at BETWEEN :from AND :to',$range),'actions'=>$this->count($d,"SELECT (SELECT COUNT(*) FROM admin_audit_log WHERE created_at BETWEEN :from1 AND :to1)+(SELECT COUNT(*) FROM project_audit_log WHERE created_at BETWEEN :from2 AND :to2)",['from1'=>$range['from'],'to1'=>$range['to'],'from2'=>$range['from'],'to2'=>$range['to']])];$roles=$d->query('SELECT r.name label,COUNT(DISTINCT ur.user_id) total FROM roles r LEFT JOIN user_roles ur ON ur.role_id=r.id GROUP BY r.id ORDER BY total DESC')->fetchAll();$statuses=$d->query("SELECT status label,COUNT(*) total FROM projects WHERE deleted_at IS NULL GROUP BY status ORDER BY total DESC")->fetchAll();$params=['from1'=>$range['from'],'to1'=>$range['to'],'from2'=>$range['from'],'to2'=>$range['to']];$union=" FROM (SELECT a.action,a.entity_type,a.created_at,u.full_name actor FROM admin_audit_log a LEFT JOIN users u ON u.id=a.actor_user_id WHERE a.created_at BETWEEN :from1 AND :to1 UNION ALL SELECT p.action,p.entity_type,p.created_at,u.full_name actor FROM project_audit_log p LEFT JOIN users u ON u.id=p.user_id WHERE p.created_at BETWEEN :from2 AND :to2) events";$activity=PaginationService::run($d,'SELECT COUNT(*)'.$union,'SELECT action,entity_type,created_at,actor'.$union.' ORDER BY created_at DESC',$params,$pagination?:PaginationService::request());return compact('summary','roles','statuses')+['activity'=>$activity['items'],'pagination'=>$activity['pagination']];}
 public function export(string $type,string $from,string $to):array{$d=Database::connection();$p=['from'=>$from.' 00:00:00','to'=>$to.' 23:59:59'];if($type==='users'){$sql="SELECT u.id,u.full_name,u.email,r.name role,u.status,u.created_at,u.last_login_at FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id WHERE u.created_at BETWEEN :from AND :to ORDER BY u.created_at";$headers=['ID','Nombre','Correo','Rol','Estado','Creado','Último acceso'];}elseif($type==='projects'){$sql="SELECT p.code,p.title,pt.name type,c.name career,ap.name period,p.status,u.full_name tutor,p.created_at,p.updated_at FROM projects p JOIN project_types pt ON pt.id=p.project_type_id JOIN careers c ON c.id=p.career_id JOIN academic_periods ap ON ap.id=p.academic_period_id LEFT JOIN users u ON u.id=p.tutor_id WHERE p.created_at BETWEEN :from AND :to ORDER BY p.created_at";$headers=['Código','Título','Tipo','Carrera','Periodo','Estado','Tutor','Creado','Actualizado'];}else{$sql="SELECT action,entity_type,entity_id,actor,created_at FROM (SELECT a.action,a.entity_type,a.entity_id,u.full_name actor,a.created_at FROM admin_audit_log a LEFT JOIN users u ON u.id=a.actor_user_id UNION ALL SELECT p.action,p.entity_type,p.entity_id,u.full_name actor,p.created_at FROM project_audit_log p LEFT JOIN users u ON u.id=p.user_id) audit WHERE created_at BETWEEN :from AND :to ORDER BY created_at";$headers=['Acción','Entidad','ID de entidad','Responsable','Fecha'];}$q=$d->prepare($sql);$q->execute($p);return ['headers'=>$headers,'rows'=>$q->fetchAll()];}
 private function count(PDO $d,string $sql,array $params):int{$q=$d->prepare($sql);$q->execute($params);return (int)$q->fetchColumn();}
}
